cd /Users/kristinarash/Library/Caches/sportsci-batch-123 && node -e '
const fs=require("fs");
for (const id of ["Q01","Q02","Q03","Q04","Q05","Q06","Q07","Q08"]) {
  const d=JSON.parse(fs.readFileSync(`drafts/${id}.json`,"utf8"));
  const over=[];
  for (const [k,v] of Object.entries(d.paper)) {
    if (typeof v!=="string" || !v) continue;
    if (k==="citation"||k==="doi"||k==="year"||k==="abstract") continue;
    const n=(v.match(/[.!?](\s|$)(?=[A-Z(])/g)||[]).length+1;
    if (n>3) over.push(k+"="+n);
  }
  const dashes=(JSON.stringify(d).match(/[—–]/g)||[]).length;
  console.log(id, "ok-json", "over3:", over.join(",")||"none", "dashes:", dashes, "pops:", d.populations.join("|"));
}'

